package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.component;
import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.DisplayName;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.ContractNodeSpec;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.ImplementationState;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill.ItemFilterSpec;
public final class BasicAttackComponentSpec extends ContractNodeSpec{public static final String VARIANT="BASIC_ATTACK";public enum BasicAttackAvailability{FULL,WEAK,NONE}private final BasicAttackAvailability availability;private final int damageNumerator,damageDenominator,actionTimeTurns;private final ItemFilterSpec allowedWeapons;public BasicAttackComponentSpec(StableId id,DisplayName name,BasicAttackAvailability availability,int numerator,int denominator,ItemFilterSpec weapons,int turns){super(id,name,NodeKind.COMPONENT,VARIANT,ImplementationState.IMPLEMENTED);if(availability==null||weapons==null||numerator<0||denominator<1||turns<1)throw new IllegalArgumentException("invalid basic attack fields");this.availability=availability;damageNumerator=numerator;damageDenominator=denominator;allowedWeapons=weapons;actionTimeTurns=turns;}public BasicAttackAvailability availability(){return availability;}public int damageNumerator(){return damageNumerator;}public int damageDenominator(){return damageDenominator;}public ItemFilterSpec allowedWeapons(){return allowedWeapons;}public int actionTimeTurns(){return actionTimeTurns;}@Override public BasicAttackComponentSpec withIdentity(StableId id){return new BasicAttackComponentSpec(id,displayName(),availability,damageNumerator,damageDenominator,allowedWeapons,actionTimeTurns);}@Override public BasicAttackComponentSpec withDisplayName(DisplayName name){return new BasicAttackComponentSpec(id(),name,availability,damageNumerator,damageDenominator,allowedWeapons,actionTimeTurns);}}
